<script>document.documentElement.classList.add('nbx-js')</script>
<style>.nbx-loader{display:none}.nbx-js .nbx-loader{position:fixed;z-index:9999;inset:0;display:grid;place-items:center;background:radial-gradient(circle at 50% 44%,#102e5d,#06101e 52%,#030914);transition:opacity .45s ease,visibility .45s ease}.nbx-loader.is-ready{opacity:0;visibility:hidden;pointer-events:none}.nbx-loader-inner{text-align:center;color:#fff}.nbx-symbol{position:relative;width:92px;height:92px;margin:auto;display:grid;place-items:center}.nbx-symbol:before,.nbx-symbol:after{content:"";position:absolute;inset:-12px;border:1px solid rgba(61,213,255,.36);border-radius:30px;transform:rotate(45deg);animation:nbx-orbit 2.2s linear infinite}.nbx-symbol:after{inset:-25px;border-color:rgba(117,87,255,.22);animation-direction:reverse;animation-duration:3.2s}.nbx-symbol img{position:relative;z-index:2;width:72px;height:72px;object-fit:contain;filter:drop-shadow(0 0 25px rgba(62,149,255,.42));animation:nbx-breathe 1.5s ease-in-out infinite}.nbx-loader strong{display:block;margin-top:27px;font:700 11px Inter,system-ui;letter-spacing:.2em}.nbx-loader small{display:block;margin-top:7px;color:#829ab9;font:500 9px Inter,system-ui;letter-spacing:.12em}@keyframes nbx-orbit{to{transform:rotate(405deg)}}@keyframes nbx-breathe{50%{transform:scale(.92);opacity:.76}}.nbx-cursor,.nbx-cursor-ring{display:none}@media(pointer:fine) and (prefers-reduced-motion:no-preference){.nbx-cursor,.nbx-cursor-ring{position:fixed;z-index:10000;left:0;top:0;display:block;pointer-events:none;border-radius:50%;opacity:0}.nbx-cursor{width:7px;height:7px;background:#36dbff;box-shadow:0 0 14px #36dbff}.nbx-cursor-ring{width:31px;height:31px;border:1px solid rgba(54,219,255,.55);transition:width .18s,height .18s,border-color .18s,background .18s}.nbx-cursor-ring.is-action{width:45px;height:45px;border-color:rgba(116,87,255,.72);background:rgba(116,87,255,.08)}body.nbx-cursor-active{cursor:none}body.nbx-cursor-active a,body.nbx-cursor-active button,body.nbx-cursor-active summary,body.nbx-cursor-active label{cursor:none}body.nbx-cursor-active input,body.nbx-cursor-active textarea,body.nbx-cursor-active select,body.nbx-cursor-active [contenteditable]{cursor:auto}}@media(prefers-reduced-motion:reduce){.nbx-symbol:before,.nbx-symbol:after,.nbx-symbol img{animation:none}}</style>
<div class="nbx-loader" id="nbxLoader" role="status" aria-label="Loading Niyantron"><div class="nbx-loader-inner"><div class="nbx-symbol"><img src="{{ asset('brand/niyantron-symbol-gradient.png') }}" alt=""></div><strong>NIYANTRON</strong><small>CONNECTED CONTROL</small></div></div><i class="nbx-cursor" id="nbxCursor"></i><i class="nbx-cursor-ring" id="nbxCursorRing"></i>
<script>(()=>{const loader=document.getElementById('nbxLoader'),dot=document.getElementById('nbxCursor'),ring=document.getElementById('nbxCursorRing'),ready=()=>loader?.classList.add('is-ready');if(document.readyState==='complete')setTimeout(ready,260);else addEventListener('load',()=>setTimeout(ready,260),{once:true});setTimeout(ready,3200);if(!matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches||!dot||!ring)return;document.body.classList.add('nbx-cursor-active');let x=innerWidth/2,y=innerHeight/2,rx=x,ry=y;addEventListener('mousemove',e=>{x=e.clientX;y=e.clientY;dot.style.opacity=ring.style.opacity='1';dot.style.transform=`translate3d(${x-3.5}px,${y-3.5}px,0)`},{passive:true});addEventListener('mouseout',e=>{if(!e.relatedTarget)dot.style.opacity=ring.style.opacity='0'});const loop=()=>{rx+=(x-rx)*.16;ry+=(y-ry)*.16;ring.style.transform=`translate3d(${rx-15.5}px,${ry-15.5}px,0)`;requestAnimationFrame(loop)};loop();document.addEventListener('mouseover',e=>ring.classList.toggle('is-action',!!e.target.closest('a,button,summary,label,[role="button"]')),{passive:true})})()</script>
